  await recheck()
  const leaseUntil = new Date(
    Math.min(
      ...[
        parent.lease_until,
        queue.lease_until,
        event.lease_until,
        ...(binding.expires_at === null ? [] : [binding.expires_at])
      ].map((value) => new Date(value as string | Date).getTime())
    )
