        publishedFenceError()
      if (b.phase_state === 'FAULTED' && !settlement) publishedFenceError()
      const p = {
        phaseId: `phase_${randomUUID()}`,
        phaseType: type,
        phaseRevision: count(b.phase_revision) + 1,
        attempt: fence.attempt,
        inputDigest: digest
