      // An OPEN segment stays OPEN after phase ACK; only saveResumePoint makes it resumable.
      await client.query(
        `UPDATE controlled_published_bindings SET phase_state=CASE WHEN phase_state='FAULTED' THEN phase_state ELSE 'OPEN' END,
