      open_phase_input_digest=$6,open_phase_attempt=$7,open_phase_acked=false WHERE tenant_id=$1 AND execution_id=$2`,
        [
          fence.tenantId,
          fence.executionId,
          p.phaseRevision,
          p.phaseId,
          type,
          digest,
          fence.attempt
        ]
      )
      await this.appendEvidence(
        client,
        b,
        `${p.phaseId}:intent`,
        'phase.intent',
        { ...p, expectedSealId: sealId },
        fence.attempt,
        settlement
      )
      await g.recheck()
      return p
    },
    settlement
  )
}

